struct ChunkMetadata {
    std::string url;
    std::string chunk;
};

struct SearchResult {
    std::string url;
    float score;
    std::vector<std::string> highlights;
    std::string full_content;
};

struct InvertedIndex {
    std::map<std::string, std::map<std::string, std::vector<int>>> index;
    std::map<std::string, std::string> documents;

    void add_document(const std::string& url, const std::string& content) {
        documents[url] = content;
        std::string lower_content = content;
        std::transform(lower_content.begin(), lower_content.end(), lower_content.begin(), ::tolower);
        std::regex word_regex("[a-z0-9]+");
        auto words_begin = std::sregex_iterator(lower_content.begin(), lower_content.end(), word_regex);
        auto words_end = std::sregex_iterator();

        int pos = 0;
        for (std::sregex_iterator i = words_begin; i != words_end; ++i) {
            std::string word = (*i).str();
            index[word][url].push_back(pos++);
        }
    }

    std::vector<SearchResult> search(const std::string& query, int k) {
        std::string lower_query = query;
        std::transform(lower_query.begin(), lower_query.end(), lower_query.begin(), ::tolower);
        std::regex word_regex("[a-z0-9]+");
        auto words_begin = std::sregex_iterator(lower_query.begin(), lower_query.end(), word_regex);
        auto words_end = std::sregex_iterator();

        std::set<std::string> query_words;
        for (std::sregex_iterator i = words_begin; i != words_end; ++i) {
            query_words.insert((*i).str());
        }

        std::map<std::string, float> url_scores;
        for (const auto& word : query_words) {
            if (index.find(word) != index.end()) {
                for (const auto& doc : index[word]) {
                    url_scores[doc.first] += doc.second.size();
                }
            }
        }

        std::vector<SearchResult> results;
        for (const auto& item : url_scores) {
            SearchResult res;
            res.url = item.first;
            res.score = item.second;
            res.full_content = documents[item.first];

            std::regex sentence_regex("[^.!?]+");
            auto sentences_begin = std::sregex_iterator(res.full_content.begin(), res.full_content.end(), sentence_regex);
            auto sentences_end = std::sregex_iterator();

            for (std::sregex_iterator i = sentences_begin; i != sentences_end; ++i) {
                std::string sentence = (*i).str();
                std::string lower_sentence = sentence;
                std::transform(lower_sentence.begin(), lower_sentence.end(), lower_sentence.begin(), ::tolower);

                bool match = false;
                for (const auto& word : query_words) {
                    if (lower_sentence.find(word) != std::string::npos) {
                        match = true;
                        break;
                    }
                }

                if (match && res.highlights.size() < 3) {
                    std::string trimmed = sentence;
                    trimmed.erase(0, trimmed.find_first_not_of(" \t\n\r"));
                    trimmed.erase(trimmed.find_last_not_of(" \t\n\r") + 1);
                    if (!trimmed.empty()) {
                        res.highlights.push_back(trimmed);
                    }
                }
            }

            results.push_back(res);
        }

        std::sort(results.begin(), results.end(), [](const SearchResult& a, const SearchResult& b) {
            return a.score > b.score;
        });

        if (results.size() > k) {
            results.resize(k);
        }

        return results;
    }

    void save(const std::string& filename) {
        std::ofstream ofs(filename, std::ios::binary);
        size_t doc_count = documents.size();
        ofs.write(reinterpret_cast<const char*>(&doc_count), sizeof(doc_count));
        for (const auto& doc : documents) {
            size_t url_len = doc.first.size();
            ofs.write(reinterpret_cast<const char*>(&url_len), sizeof(url_len));
            ofs.write(doc.first.c_str(), url_len);
            size_t content_len = doc.second.size();
            ofs.write(reinterpret_cast<const char*>(&content_len), sizeof(content_len));
            ofs.write(doc.second.c_str(), content_len);
        }

        size_t word_count = index.size();
        ofs.write(reinterpret_cast<const char*>(&word_count), sizeof(word_count));
        for (const auto& word_entry : index) {
            size_t word_len = word_entry.first.size();
            ofs.write(reinterpret_cast<const char*>(&word_len), sizeof(word_len));
            ofs.write(word_entry.first.c_str(), word_len);

            size_t url_count = word_entry.second.size();
            ofs.write(reinterpret_cast<const char*>(&url_count), sizeof(url_count));
            for (const auto& url_entry : word_entry.second) {
                size_t url_len = url_entry.first.size();
                ofs.write(reinterpret_cast<const char*>(&url_len), sizeof(url_len));
                ofs.write(url_entry.first.c_str(), url_len);

                size_t pos_count = url_entry.second.size();
                ofs.write(reinterpret_cast<const char*>(&pos_count), sizeof(pos_count));
                ofs.write(reinterpret_cast<const char*>(url_entry.second.data()), pos_count * sizeof(int));
            }
        }
    }

    void load(const std::string& filename) {
        std::ifstream ifs(filename, std::ios::binary);
        if (!ifs.is_open()) return;

        size_t doc_count;
        ifs.read(reinterpret_cast<char*>(&doc_count), sizeof(doc_count));
        for (size_t i = 0; i < doc_count; ++i) {
            size_t url_len;
            ifs.read(reinterpret_cast<char*>(&url_len), sizeof(url_len));
            std::string url(url_len, '\0');
            ifs.read(&url[0], url_len);

            size_t content_len;
            ifs.read(reinterpret_cast<char*>(&content_len), sizeof(content_len));
            std::string content(content_len, '\0');
            ifs.read(&content[0], content_len);

            documents[url] = content;
        }

        size_t word_count;
        ifs.read(reinterpret_cast<char*>(&word_count), sizeof(word_count));
        for (size_t i = 0; i < word_count; ++i) {
            size_t word_len;
            ifs.read(reinterpret_cast<char*>(&word_len), sizeof(word_len));
            std::string word(word_len, '\0');
            ifs.read(&word[0], word_len);

            size_t url_count;
            ifs.read(reinterpret_cast<char*>(&url_count), sizeof(url_count));
            for (size_t j = 0; j < url_count; ++j) {
                size_t url_len;
                ifs.read(reinterpret_cast<char*>(&url_len), sizeof(url_len));
                std::string url(url_len, '\0');
                ifs.read(&url[0], url_len);

                size_t pos_count;
                ifs.read(reinterpret_cast<char*>(&pos_count), sizeof(pos_count));
                std::vector<int> positions(pos_count);
                ifs.read(reinterpret_cast<char*>(positions.data()), pos_count * sizeof(int));

                index[word][url] = positions;
            }
        }
    }
};

size_t WriteCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    ((std::string*)userp)->append((char*)contents, size * nmemb);
    return size * nmemb;
}

std::string strip_html_tags(const std::string& html) {
    std::string result;
    bool in_tag = false;
    bool in_script_style = false;
    std::string tag_buffer;

    for (size_t i = 0; i < html.size(); ++i) {
        if (html[i] == '<') {
            in_tag = true;
            tag_buffer.clear();
        } else if (html[i] == '>') {
            in_tag = false;
            std::string lower_tag = tag_buffer;
            std::transform(lower_tag.begin(), lower_tag.end(), lower_tag.begin(), ::tolower);
            if (lower_tag.find("script") != std::string::npos || lower_tag.find("style") != std::string::npos) {
                if (lower_tag[0] != '/') {
                    in_script_style = true;
                } else {
                    in_script_style = false;
                }
            }
        } else if (in_tag) {
            tag_buffer += html[i];
        } else if (!in_script_style) {
            result += html[i];
        }
    }

    std::regex space_regex("\\s+");
    result = std::regex_replace(result, space_regex, " ");

    result.erase(0, result.find_first_not_of(" \t\n\r"));
    result.erase(result.find_last_not_of(" \t\n\r") + 1);

    return result;
}

class SearchEngine {
private:
    Ort::Env env;
    Ort::SessionOptions session_options;
    Ort::Session* session;
    faiss::IndexFlatIP* vector_index;
    std::vector<ChunkMetadata> metadata;
    std::map<std::string, std::string> doc_store;
    InvertedIndex keyword_index;
    int dimension;

public:
    SearchEngine() : env(ORT_LOGGING_LEVEL_WARNING, "SearchEngine"), dimension(384) {
        session_options.SetIntraOpNumThreads(1);
        session_options.SetGraphOptimizationLevel(GraphOptimizationLevel::ORT_ENABLE_EXTENDED);

        struct stat buffer;
        if (stat("model.onnx", &buffer) == 0) {
            session = new Ort::Session(env, "model.onnx", session_options);
        } else {
            session = nullptr;
        }

        if (stat("faiss.index", &buffer) == 0 && stat("metadata.bin", &buffer) == 0 && stat("doc_store.bin", &buffer) == 0) {
            vector_index = dynamic_cast<faiss::IndexFlatIP*>(faiss::read_index("faiss.index"));
            load_metadata();
            load_doc_store();
        } else {
            vector_index = new faiss::IndexFlatIP(dimension);
        }

        if (stat("keyword_index.bin", &buffer) == 0) {
            keyword_index.load("keyword_index.bin");
        }
    }

    ~SearchEngine() {
        delete vector_index;
        if (session) delete session;
    }

    std::vector<std::string> chunk_text(const std::string& text, int max_chunk_size = 1000, int overlap = 200) {
        std::vector<std::string> chunks;
        int start = 0;
        while (start < text.size()) {
            int end = start + max_chunk_size;
            if (end > text.size()) end = text.size();
            std::string chunk = text.substr(start, end - start);
            chunk.erase(0, chunk.find_first_not_of(" \t\n\r"));
            chunk.erase(chunk.find_last_not_of(" \t\n\r") + 1);
            if (!chunk.empty()) {
                chunks.push_back(chunk);
            }
            start = end - overlap;
            if (start >= text.size()) break;
        }
        return chunks;
    }

    std::string crawl(const std::string& url) {
        CURL* curl;
        CURLcode res;
        std::string readBuffer;

        curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);
            curl_easy_setopt(curl, CURLOPT_USERAGENT, "Mozilla/5.0 (compatible; SearchBot/1.0)");
            curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
            curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
            res = curl_easy_perform(curl);

            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            curl_easy_cleanup(curl);

            if (res != CURLE_OK || response_code != 200) {
                return "";
            }

            if (readBuffer.find("<meta") != std::string::npos && readBuffer.find("noindex") != std::string::npos) {
                return "";
            }

            return strip_html_tags(readBuffer);
        }
        return "";
    }

    std::vector<float> encode(const std::string& text) {
        if (!session) {
            std::vector<float> dummy(dimension, 0.0f);
            for (int i = 0; i < dimension; ++i) {
                dummy[i] = static_cast<float>(rand()) / RAND_MAX;
            }
            float norm = 0;
            for (float v : dummy) norm += v * v;
            norm = sqrt(norm);
            for (float& v : dummy) v /= norm;
            return dummy;
        }

        std::vector<int64_t> input_ids;
        std::regex word_regex("[a-zA-Z0-9]+");
        auto words_begin = std::sregex_iterator(text.begin(), text.end(), word_regex);
        auto words_end = std::sregex_iterator();

        input_ids.push_back(101);
        for (std::sregex_iterator i = words_begin; i != words_end; ++i) {
            std::string word = (*i).str();
            int token_id = (std::hash<std::string>{}(word) % 30000) + 1000;
            input_ids.push_back(token_id);
            if (input_ids.size() >= 128) break;
        }
        input_ids.push_back(102);

        while (input_ids.size() < 128) {
            input_ids.push_back(0);
        }

        std::vector<int64_t> attention_mask(128, 1);
        for (size_t i = input_ids.size(); i < 128; ++i) {
            attention_mask[i] = 0;
        }

        std::vector<int64_t> input_shape = {1, 128};
        auto memory_info = Ort::MemoryInfo::CreateCpu(OrtArenaAllocator, OrtMemTypeDefault);

        Ort::Value input_ids_tensor = Ort::Value::CreateTensor<int64_t>(
            memory_info, input_ids.data(), input_ids.size(), input_shape.data(), input_shape.size());
        Ort::Value attention_mask_tensor = Ort::Value::CreateTensor<int64_t>(
            memory_info, attention_mask.data(), attention_mask.size(), input_shape.data(), input_shape.size());

        const char* input_names[] = {"input_ids", "attention_mask"};
        const char* output_names[] = {"last_hidden_state"};
        std::vector<Ort::Value> input_tensors;
        input_tensors.push_back(std::move(input_ids_tensor));
        input_tensors.push_back(std::move(attention_mask_tensor));

        auto output_tensors = session->Run(Ort::RunOptions{nullptr}, input_names, input_tensors.data(), 2, output_names, 1);

        float* floatarr = output_tensors[0].GetTensorMutableData<float>();
        auto shape_info = output_tensors[0].GetTensorTypeAndShapeInfo();
        size_t total_size = shape_info.GetElementCount();

        std::vector<float> embeddings(dimension, 0.0f);
        int seq_len = 128;
        for (int i = 0; i < dimension && i < total_size / seq_len; ++i) {
            float sum = 0;
            for (int j = 0; j < seq_len; ++j) {
                sum += floatarr[j * dimension + i];
            }
            embeddings[i] = sum / seq_len;
        }

        float norm = 0;
        for (float v : embeddings) norm += v * v;
        norm = sqrt(norm);
        if (norm > 0) {
            for (float& v : embeddings) v /= norm;
        }

        return embeddings;
    }

    bool add_to_index(const std::string& url) {
        std::string text = crawl(url);
        if (text.empty()) {
            return false;
        }

        doc_store[url] = text;

        std::vector<std::string> chunks = chunk_text(text);
        std::vector<std::vector<float>> chunk_embs;

        for (const auto& chunk : chunks) {
            std::vector<float> emb = encode(chunk);
            chunk_embs.push_back(emb);
            ChunkMetadata meta;
            meta.url = url;
            meta.chunk = chunk;
            metadata.push_back(meta);
        }

        if (!chunk_embs.empty()) {
            std::vector<float> all_embs;
            for (const auto& emb : chunk_embs) {
                all_embs.insert(all_embs.end(), emb.begin(), emb.end());
            }
            vector_index->add(chunk_embs.size(), all_embs.data());
        }

        keyword_index.add_document(url, text);

        save();
        return true;
    }

    void save() {
        faiss::write_index(vector_index, "faiss.index");
        save_metadata();
        save_doc_store();
        keyword_index.save("keyword_index.bin");
    }

    void save_metadata() {
        std::ofstream ofs("metadata.bin", std::ios::binary);
        size_t count = metadata.size();
        ofs.write(reinterpret_cast<const char*>(&count), sizeof(count));
        for (const auto& meta : metadata) {
            size_t url_len = meta.url.size();
            ofs.write(reinterpret_cast<const char*>(&url_len), sizeof(url_len));
            ofs.write(meta.url.c_str(), url_len);
            size_t chunk_len = meta.chunk.size();
            ofs.write(reinterpret_cast<const char*>(&chunk_len), sizeof(chunk_len));
            ofs.write(meta.chunk.c_str(), chunk_len);
        }
    }

    void load_metadata() {
        std::ifstream ifs("metadata.bin", std::ios::binary);
        if (!ifs.is_open()) return;
        size_t count;
        ifs.read(reinterpret_cast<char*>(&count), sizeof(count));
        metadata.clear();
        for (size_t i = 0; i < count; ++i) {
            ChunkMetadata meta;
            size_t url_len;
            ifs.read(reinterpret_cast<char*>(&url_len), sizeof(url_len));
            meta.url.resize(url_len);
            ifs.read(&meta.url[0], url_len);
            size_t chunk_len;
            ifs.read(reinterpret_cast<char*>(&chunk_len), sizeof(chunk_len));
            meta.chunk.resize(chunk_len);
            ifs.read(&meta.chunk[0], chunk_len);
            metadata.push_back(meta);
        }
    }

    void save_doc_store() {
        std::ofstream ofs("doc_store.bin", std::ios::binary);
        size_t count = doc_store.size();
        ofs.write(reinterpret_cast<const char*>(&count), sizeof(count));
        for (const auto& doc : doc_store) {
            size_t url_len = doc.first.size();
            ofs.write(reinterpret_cast<const char*>(&url_len), sizeof(url_len));
            ofs.write(doc.first.c_str(), url_len);
            size_t content_len = doc.second.size();
            ofs.write(reinterpret_cast<const char*>(&content_len), sizeof(content_len));
            ofs.write(doc.second.c_str(), content_len);
        }
    }

    void load_doc_store() {
        std::ifstream ifs("doc_store.bin", std::ios::binary);
        if (!ifs.is_open()) return;
        size_t count;
        ifs.read(reinterpret_cast<char*>(&count), sizeof(count));
        doc_store.clear();
        for (size_t i = 0; i < count; ++i) {
            size_t url_len;
            ifs.read(reinterpret_cast<char*>(&url_len), sizeof(url_len));
            std::string url(url_len, '\0');
            ifs.read(&url[0], url_len);
            size_t content_len;
            ifs.read(reinterpret_cast<char*>(&content_len), sizeof(content_len));
            std::string content(content_len, '\0');
            ifs.read(&content[0], content_len);
            doc_store[url] = content;
        }
    }

    std::string get_domain(const std::string& url) {
        std::regex domain_regex("://([^/]+)");
        std::smatch match;
        if (std::regex_search(url, match, domain_regex)) {
            return match[1].str();
        }
        return "";
    }

    std::vector<SearchResult> search(const std::string& query, const std::string& search_type, int k) {
        std::string original_url;
        std::string actual_query = query;
        std::string actual_search_type = search_type;

        if (query.substr(0, 4) == "http") {
            original_url = query;
            std::string qtext = crawl(query);
            if (!qtext.empty()) {
                actual_query = qtext;
            }
            actual_search_type = "neural";
        }

        if (actual_search_type == "auto") {
            std::regex word_regex("\\S+");
            auto words_begin = std::sregex_iterator(actual_query.begin(), actual_query.end(), word_regex);
            auto words_end = std::sregex_iterator();
            int word_count = std::distance(words_begin, words_end);
            actual_search_type = (word_count > 4) ? "neural" : "keyword";
        }

        if (actual_search_type == "neural") {
            std::vector<float> qemb = encode(actual_query);
            std::vector<float> distances(k * 10);
            std::vector<faiss::idx_t> indices(k * 10);
            vector_index->search(1, qemb.data(), k * 10, distances.data(), indices.data());

            std::map<std::string, std::vector<std::pair<float, std::string>>> url_scores;
            for (int i = 0; i < k * 10; ++i) {
                if (indices[i] == -1) continue;
                if (indices[i] >= metadata.size()) continue;
                ChunkMetadata meta = metadata[indices[i]];
                url_scores[meta.url].push_back({distances[i], meta.chunk});
            }

            std::vector<SearchResult> results;
            for (auto& item : url_scores) {
                SearchResult res;
                res.url = item.first;

                float best_score = 0;
                for (const auto& sc : item.second) {
                    if (sc.first > best_score) best_score = sc.first;
                }
                res.score = best_score;

                std::sort(item.second.begin(), item.second.end(), [](const auto& a, const auto& b) {
                    return a.first > b.first;
                });

                for (size_t i = 0; i < std::min(size_t(3), item.second.size()); ++i) {
                    res.highlights.push_back(item.second[i].second);
                }

                if (doc_store.find(item.first) != doc_store.end()) {
                    res.full_content = doc_store[item.first];
                }

                results.push_back(res);
            }

            std::sort(results.begin(), results.end(), [](const SearchResult& a, const SearchResult& b) {
                return a.score > b.score;
            });

            if (!original_url.empty()) {
                std::string orig_domain = get_domain(original_url);
                for (auto& res : results) {
                    std::string res_domain = get_domain(res.url);
                    if (orig_domain == res_domain) {
                        res.score *= 1.2f;
                    }
                }
                std::sort(results.begin(), results.end(), [](const SearchResult& a, const SearchResult& b) {
                    return a.score > b.score;
                });
            }

            if (results.size() > k) {
                results.resize(k);
            }

            return results;
        } else {
            return keyword_index.search(actual_query, k);
        }
    }

    std::string get_content(const std::string& url) {
        if (doc_store.find(url) != doc_store.end()) {
            return doc_store[url];
        }
        return "";
    }
};

int main() {
    SearchEngine se;

    crow::SimpleApp app;

    CROW_ROUTE(app, "/add").methods("POST"_method)
    ([&se](const crow::request& req) {
        auto body = crow::json::load(req.body);
        if (!body) {
            return crow::response(400, "{\"error\":\"Invalid JSON\"}");
        }

        std::string url = body["url"].s();
        if (url.empty()) {
            return crow::response(400, "{\"error\":\"URL required\"}");
        }

        bool success = se.add_to_index(url);
        std::string status = success ? "added" : "failed";
        return crow::response("{\"status\":\"" + status + "\"}");
    });

    CROW_ROUTE(app, "/search").methods("GET"_method, "POST"_method)
    ([&se](const crow::request& req) {
        std::string query;
        int k = 10;
        std::string search_type = "auto";

        if (req.method == "POST"_method) {
            auto body = crow::json::load(req.body);
            if (body) {
                query = body["q"].s();
                if (body.has("k")) {
                    k = body["k"].i();
                }
                if (body.has("type")) {
                    search_type = body["type"].s();
                }
            }
        } else {
            query = req.url_params.get("q") ? req.url_params.get("q") : "";
            k = req.url_params.get("k") ? std::stoi(req.url_params.get("k")) : 10;
            search_type = req.url_params.get("type") ? req.url_params.get("type") : "auto";
        }

        std::vector<SearchResult> results = se.search(query, search_type, k);

        crow::json::wvalue response = crow::json::wvalue::list();
        for (size_t i = 0; i < results.size(); ++i) {
            crow::json::wvalue item;
            item["url"] = results[i].url;
            item["score"] = results[i].score;
            item["full_content"] = results[i].full_content;

            crow::json::wvalue highlights = crow::json::wvalue::list();
            for (size_t j = 0; j < results[i].highlights.size(); ++j) {
                highlights[j] = results[i].highlights[j];
            }
            item["highlights"] = std::move(highlights);

            response[i] = std::move(item);
        }

        return crow::response(response);
    });

    CROW_ROUTE(app, "/get_content")
    ([&se](const crow::request& req) {
        std::string url = req.url_params.get("url") ? req.url_params.get("url") : "";
        if (url.empty()) {
            return crow::response(400, "{\"error\":\"URL required\"}");
        }

        std::string content = se.get_content(url);
        crow::json::wvalue response;
        response["content"] = content;
        return crow::response(response);
    });

